  #[local] Notation lazy_cover_vis := (AsanNodesAuxK.lazy_cover_vis SEGS A LIMIT SINV argH FS0 HULL_ok).
  #[local] Notation H_off_segments_vis := (AsanNodesAuxK.H_off_segments_vis SEGS A SEGS_in_hull).

