    regs_ok E sr R -> APK.sr_vars_lt nx sr = true -> Forall (fun r => 0 < r < 32)%nat rs ->
    (forall q : bv 5, (forall n, In n rs -> q <> Z_to_bv 5 (Z.of_nat n)) -> getr R' q = getr R q) ->
